import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../App.css';

export default function PaginaInicial() {
  const [produtosFiltrados, setProdutosFiltrados] = useState([]);
  const [filtro, setFiltro] = useState('');
  const [categorias, setCategorias] = useState([]);
  const [categoriaSelecionada, setCategoriaSelecionada] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    fetch('http://localhost:5000/categorias')
      .then(res => res.json())
      .then(data => setCategorias(data))
      .catch(err => console.error('Erro ao buscar categorias:', err));
  }, []);

  useEffect(() => {
    let url = 'http://localhost:5000/produtos';

    const termo = filtro.trim();
    if (termo) {
      url = `http://localhost:5000/produtos/buscar?q=${encodeURIComponent(termo)}`;
    } else if (categoriaSelecionada) {
      url = `http://localhost:5000/produtos/categoria/${categoriaSelecionada}`;
    }

    fetch(url)
      .then(res => res.json())
      .then(data => setProdutosFiltrados(data))
      .catch(err => {
        console.error('Erro ao buscar produtos:', err);
        setProdutosFiltrados([]);
      });
  }, [filtro, categoriaSelecionada]);

  function irParaPerfil() {
    navigate('/perfil');
  }

  function abrirDetalhes(id) {
    navigate(`/produto/${id}`);
  }

  function irParaAdicionarProduto() {
    navigate('/adicionar-produto');
  }

  function irParaCarrinho() {
    navigate('/carrinho');
  }

  function adicionarAoCarrinho(e, produtoId) {
    e.stopPropagation();
    fetch('http://localhost:5000/carrinho', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ produto_id: produtoId }),
    })
      .then(res => res.json())
      .then(data => alert(data.mensagem || data.erro))
      .catch(() => alert('Erro ao adicionar ao carrinho'));
  }

  return (
    <div className="pagina-inicial">
      <header className="header">
        <h1>Catálogo de Tênis</h1>
        <div className="botoes-topo">
          <button className="botao-perfil" onClick={irParaPerfil}>Meu Perfil</button>
          <button className="botao-adicionar" onClick={irParaAdicionarProduto}>Cadastrar Tênis</button>
          <button
            className="botao-carrinho topo"
            onClick={irParaCarrinho}
            aria-label="Ver carrinho de compras"
            title="Ver carrinho"
          >
            {/* Ícone de tênis (em vez de carrinho) */}
            <svg className="icone-tenis" xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M4 17c0-2 1.5-5 4-6l6-2 5 1 2 3v3H4z" />
              <path d="M2 17h20" />
            </svg>
          </button>
        </div>
      </header>

      {/* Barra de busca com classe */}
      <div className="filtros-container">
        <input
          type="text"
          placeholder="Buscar tênis pelo nome..."
          value={filtro}
          onChange={e => {
            setFiltro(e.target.value);
            setCategoriaSelecionada('');
          }}
          className="barra-pesquisa"
        />

        {/* Filtro de categoria com classe */}
        <select
          value={categoriaSelecionada}
          onChange={e => {
            setCategoriaSelecionada(e.target.value);
            setFiltro('');
          }}
          className="select-categoria"
        >
          <option value="">Filtrar por categoria...</option>
          {categorias.map(c => (
            <option key={c.id} value={c.id}>{c.nome}</option>
          ))}
        </select>
      </div>

      <div className="lista-produtos">
        {produtosFiltrados.length === 0 ? (
          <p>Nenhum tênis encontrado.</p>
        ) : (
          produtosFiltrados.map(produto => (
            <div
              key={produto.id}
              className="card-produto"
              onClick={() => abrirDetalhes(produto.id)}
            >
              <img
                src={produto.imagem_url}
                alt={produto.nome}
                className="imagem-produto"
                onError={(e) => {
                  e.target.onerror = null;
                  e.target.src = '/img/imagem-nao-disponivel.png';
                }}
              />
              <h3>{produto.nome}</h3>
              <p>Preço: R$ {produto.preco.toFixed(2)}</p>
              <button
                className="botao-carrinho card"
                onClick={(e) => adicionarAoCarrinho(e, produto.id)}
                aria-label={`Adicionar ${produto.nome} à sacola`}
                title="Adicionar à sacola"
              >
                {/* Ícone de tênis */}
<svg
  xmlns="http://www.w3.org/2000/svg"
  width="24"
  height="24"
  viewBox="0 0 64 64"
  fill="none"
  stroke="currentColor"
  strokeWidth="2"
  strokeLinecap="round"
  strokeLinejoin="round"
>
  {/* Sola */}
  <path d="M8 44h48v6a4 4 0 0 1-4 4H12a4 4 0 0 1-4-4v-6z" fill="#ccc" />
  {/* Corpo do tênis */}
  <path d="M12 44l8-24h24l8 12-8 10H20l-8-6z" fill="none" />
  <path d="M20 20l6 4M28 20l6 4M36 20l6 4" />
  {/* Cadarços */}
  <line x1="18" y1="38" x2="46" y2="38" />
  <line x1="18" y1="34" x2="46" y2="34" />
  <line x1="18" y1="30" x2="46" y2="30" />
  {/* Contorno do tênis */}
  <path d="M12 44l8-24h24l8 12-8 10H20l-8-6z" />
</svg>
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
